const rawBody = $json.body ?? $json;
const message = (rawBody.message ?? rawBody.text ?? '').toString().trim();
const userId = (rawBody.userId ?? rawBody.user ?? 'anonymous').toString().trim();
const sessionId = (rawBody.sessionId ?? rawBody.conversationId ?? userId).toString().trim();
const userContext = rawBody.userContext ?? {};
const modo = rawBody.modo ?? 'corvus';
const rawImages = Array.isArray(rawBody.imageAttachments) ? rawBody.imageAttachments : (Array.isArray(rawBody.images) ? rawBody.images : []);
const imageAttachments = rawImages.filter((item) => (item?.dataUrl || item?.imageUrl || item?.url || item?.signedUrl) && item?.type?.startsWith?.('image/'));
const imageSummary = imageAttachments.map((item, index) => {
  const label = item.name || `imagem-${index + 1}`;
  const imageUrl = item.dataUrl || item.imageUrl || item.url || item.signedUrl;
  return `${index + 1}. ${label} (${item.type || 'image/*'}) - ${imageUrl}`;
}).join('\n');

if (!message) {
  return [{ ok: false, error: "Missing 'message'" }];
}

return [{ ok: true, message, userId, sessionId, userContext, modo, imageAttachments, imageSummary, hasImages: imageAttachments.length > 0 || rawBody.hasImages === true, receivedAt: new Date().toISOString() }];

const out = $input.first().json;
const reply = (out.output ?? out.text ?? out.response ?? '').toString().trim();

return {
  json: {
    ok: true,
    reply: reply || 'Sem resposta do agente.',
    meta: {
      agent: 'Corvus 2.0',
      model: 'gpt-4o',
      database: 'supabase-pgvector'
    }
  }
};

